package net.zartra.gui;
final class MenuAction { enum Type { PLAYER_COMMAND, CONSOLE_COMMAND, OP_COMMAND, MESSAGE, BROADCAST, ACTION_BAR, CLOSE_MENU, REFRESH_MENU, OPEN_MENU, CONNECT_SERVER, GIVE_ITEM, HEAL, FEED, SET_HEALTH, SET_FOOD, SET_FLY, CLEAR_POTION_EFFECTS, SOUND, TELEPORT_WORLD, TELEPORT, SET_GAMEMODE, POTION_EFFECT, REMOVE_POTION_EFFECT, SET_VARIABLE, ADD_VARIABLE, REMOVE_VARIABLE, TOGGLE_VARIABLE, WAIT } final Type type; final String value; MenuAction(Type type,String value){this.type=type;this.value=value==null?"":value;} static MenuAction parse(String raw){if(raw==null)return null;String[] p=raw.split(":",2);try{String id=p[0].trim().toUpperCase();if("CLOSE".equals(id))id="CLOSE_MENU";if("REFRESH".equals(id))id="REFRESH_MENU";return new MenuAction(Type.valueOf(id),p.length>1?p[1].trim():"");}catch(IllegalArgumentException e){return null;}} String save(){return type.name()+(value.length()==0?"":": "+value);} }